{
  "title": "迷雾山林",
  "scene": "你行走在一片浓雾笼罩的山林中，只听得溪水潺潺，偶尔传来几声鸟鸣。前方有一座破旧的小木屋，门半开着，隐约可见屋内有微弱的烛光。在木屋旁边，有一棵古老的松树，树根处放着一个用红布包裹的包袱。你想起江湖传言，说这里曾有一位隐居的武林高手，不知是否还在。此时，一阵风吹过，松树的枝叶轻柔地摇曳，仿佛在向你低语。",
  "goal": "找到隐居的武林高手，获取武功秘籍。",
  "clue": "松树根处的红布包裹的包袱",
  "choices": [
    {
      "id": "A",
      "text": "敲门进入木屋",
      "outcome": "你轻轻敲了敲门，里面传来一阵苍老的声音：‘进来吧。’你推开门，发现屋内坐着一位白发苍苍的老者，正在研读一本古朴的书。老者见你进来，微笑着说道：‘年轻人，你来得正好，我正打算将这武功秘籍传给有缘人。’",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "捡起红布包裹的包袱",
      "outcome": "你走近松树，小心翼翼地捡起红布包裹的包袱。打开一看，里面是一本泛黄的武功秘籍。正当你准备翻开时，一阵风吹过，秘籍被卷走，消失在浓雾中。老者从木屋中走出，摇头叹息：‘年轻人，心急吃不了热豆腐啊。’",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "在木屋周围观察",
      "outcome": "你在木屋周围仔细观察，发现屋后有一条隐秘的小径。沿着小径走去，你发现了一个小花园，花园中有一位白发苍苍的老者正在练剑。老者见你前来，停下剑法，说道：‘年轻人，你眼力不错，这武功秘籍就传给你吧。’",
      "result": "partial",
      "next": "next_level"
    }
  ]
}
